    dp = [[0] * (N+1) for _ in range(N+1)]

    # Populate the dynamic programming table
    for i in range(N):
        for j in range(N):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + grid_values[i][j]

    # Find the maximum value on the two paths
    max_value = 0
    for i in range(N):
        for j in range(N):
            if dp[i][j] > max_value:
                max_value = dp[i][j]

    return max_value

