def max_happiness(n, m, items):
    # Initialize a 2D table to store the results of subproblems
    dp = [[0] * (m+1) for _ in range(n+1)]

    # Loop through the items
    for i in range(1, m+1):
        # Loop through the budget
        for j in range(1, n+1):
            # Check if the current item's price is less than or equal to the current budget
            if items[i-1][0] <= j:
                # Update the maximum happiness with the current item included
                dp[j][i] = max(dp[j][i-1], dp[j-items[i-1][0]][i-1] + items[i-1][1])
            else:
                # Update the maximum happiness with the current item excluded
                dp[j][i] = dp[j][i-1]

    # Return the maximum happiness
    return dp[n][m]

def polynomial_to_string(n, coeffs):
    result = ""
    for i in range(n, -1, -1):
        if coeffs[i] != 0:
            sign = "+" if coeffs[i] > 0 else ""
            abs_coeff = abs(coeffs[i])
            if abs_coeff == 1 and i > 0:
                abs_coeff = ""
            else:
                abs_coeff = str(abs_coeff)
            result += f"{sign}{abs_coeff}x^{i}"
    return result.strip()

def decode(encoded: str, original: str, message: str) -> str:
    # Build a mapping from encoded letters to their original letters
    letter_map = {}
    for i, letter in enumerate(encoded):
        if letter not in letter_map:
            letter_map[letter] = original[i]
        else:
            if letter_map[letter] != original[i]:
                return "Failed"

    # Use the mapping to decode the message
    decoded = ""
    for letter in message:
        if letter in letter_map:
            decoded += letter_map[letter]
        else:
            return "Failed"

    return decoded

def count_partitions(n, k, x):
    # Initialize a 2D array to store the results
    dp = [[0] * (k+1) for _ in range(n+1)]

    # Initialize the first row and column with 1s
    for i in range(k+1):
        dp[0][i] = 1
    for i in range(n+1):
        dp[i][0] = 1

    # Fill in the rest of the 2D array using the recurrence relation
    for i in range(1, n+1):
        for j in range(1, k+1):
            for l in range(x, i+1):
                dp[i][j] += dp[i-l][j-1]

    # Return the last entry of the last row
    return dp[n][k]

def count_sequences(n, last, memo):
    if last in memo:
        return memo[last]
    if last == n:
        return 1
    count = 0
    for i in range(1, last):
        if i <= last // 2:
            count += count_sequences(n, i, memo)
    memo[last] = count
    return count

